/**
 * Builds the text MCPJam's picker reads as its method: the climb skill
 * (`skills/climb-an-mcp-server`), its frontmatter removed, with its two
 * references after it. The server bundle has no skills directory, so the text
 * is inlined here the way `mcp/scripts/generate-skills-bundle.mjs` inlines it
 * for the Worker, and a test fails when the generated file lags the skill.
 *
 *   node scripts/generate-picker-skill.mjs          write the generated file
 *   node scripts/generate-picker-skill.mjs --check  exit 1 when it is stale
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const SKILL_DIR = join(here, "../../skills/climb-an-mcp-server");
const OUTPUT = join(here, "../server/services/climbs/picker-skill.generated.ts");

export function pickerSkillText() {
  const body = readFileSync(join(SKILL_DIR, "SKILL.md"), "utf8").replace(/^---\n[\s\S]*?\n---\n/, "").trim();
  const references = ["references/playbook.md", "references/rounds.md"].map((path) =>
    readFileSync(join(SKILL_DIR, path), "utf8").trim(),
  );
  return [body, ...references].join("\n\n---\n\n");
}

export function generatedModule() {
  return `// Generated by scripts/generate-picker-skill.mjs from skills/climb-an-mcp-server. Do not edit.\n\nexport const PICKER_SKILL_TEXT: string = ${JSON.stringify(pickerSkillText())};\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = generatedModule();
  if (process.argv.includes("--check")) {
    let current = "";
    try {
      current = readFileSync(OUTPUT, "utf8");
    } catch {
      // A missing file is stale too.
    }
    if (current !== next) {
      process.stderr.write("picker-skill.generated.ts is stale: run node scripts/generate-picker-skill.mjs\n");
      process.exit(1);
    }
  } else {
    writeFileSync(OUTPUT, next);
  }
}
